import {p,h,ul,table,link,img,doc} from './reconcile-whitepaper-full-20261002.mjs';
for(const l of ['en','tc']){
 const tc=l==='tc',t=(en,zh)=>tc?zh:en;
 doc(l,'/learning/governance',t('Governance — design and responsibilities','治理 · 設計與職責'),p(t('Governance is intended to make protocol changes and resource decisions reviewable. The roles below are a design proposal; this chapter does not establish that a governor, timelock or guardian committee is already deployed.','治理旨在使協議變更與資源決策可供審閱。下列角色屬設計方案；本章不表示治理合約、時間鎖或守護者委員會已部署。'))+h('section-1',t('Decision scope','決策範圍'))+ul([t('Protocol parameters, upgrades and the permissions needed to execute them.','協議參數、升級及執行所需權限。'),t('Vault eligibility, reward budgets and ecosystem funding within the applicable allocation rules.','適用分配規則內的金庫資格、獎勵預算與生態資助。'),t('Publication of proposals, decisions, execution transactions and exceptions.','公布提案、決定、執行交易及例外處理。')])+h('section-2',t('Operational roles','執行角色'))+table([t('Role','角色'),t('Proposed boundary','擬議權限邊界')],[['Manager',t('Carry out authorised operations; any emergency pause requires a defined scope and follow-up disclosure.','執行獲授權操作；緊急暫停須有明確範圍及後續披露。')],['Authorizer',t('Enforce permissions between approved decisions and contract calls.','在獲批決策與合約呼叫之間執行權限控制。')],['Coordinator',t('Coordinate execution order and dependencies; cancellation or delay powers must be explicit.','協調執行次序與依賴；取消或延遲權限須明列。')]])+h('section-3',t('Voting rights and activation','投票權與啟用'))+p(t('The design references both MHA participation and mBGT reward coordination/protocol voting. Their relationship, delegation model and eligible voting supply must be confirmed together. Holding BSC MHA does not by itself demonstrate access to a live on-chain governor. Activation should publish the network, contract addresses, vote accounting, timelock and emergency permissions.','設計稿同時提及 MHA 參與及 mBGT 獎勵協調／協議投票。兩者關係、委託方式與合資格投票供應量須一併確認。持有 BSC MHA 本身不表示已可使用正式鏈上治理。啟用時應公布網絡、合約地址、票數計算、時間鎖及緊急權限。'))+p(link(l,'/learning/gov-overview',t('Proposed lifecycle and parameters','擬議流程與參數'))));
 doc(l,'/learning/gov-overview',t('Governance lifecycle — proposed parameters','治理流程 · 擬議參數'),h('section-1',t('Design status','設計狀態'))+p(t('The following retains earlier governance design parameters for review. They are not current operating instructions. MHA/mBGT voting rights and the voting-supply denominator require confirmation before these parameters can be adopted.','以下保留早期治理設計參數供審閱，不是現行操作指引。採用前須確認 MHA／mBGT 投票權及投票供應量的分母。'))+h('section-2',t('Proposed use cases','擬議使用範圍'))+p(t('Protocol settings, reward-vault admission, application permissions and ecosystem budgets may be proposed within a published governance scope. Economic allocation changes require explicit proposals rather than being implied by an operational vote.','可在已公布的治理範圍內，就協議設定、獎勵金庫准入、應用權限及生態預算提出提案。經濟分配變更須明確提出，不由一般操作投票默認推導。'))+h('section-3',t('Lifecycle','生命週期'))+ul([t('Publish a proposal with purpose, affected contracts, funding source and executable actions.','公布提案目的、影響合約、資金來源及可執行操作。'),t('Take the voting-power snapshot, apply the pending period and open voting.','記錄投票權快照、經待啟動期後開放投票。'),t('Check quorum and the approval rule, then queue approved actions in the timelock.','核對法定參與及通過條件，再將獲批操作排入時間鎖。'),t('Execute after the delay and disclose transaction results; emergency cancellation follows separately defined authority.','延遲期後執行並披露交易結果；緊急取消須遵循另行定義的權限。')])+h('section-4',t('Guardian proposal','守護者方案'))+p(t('The earlier 5-of-9 guardian proposal would allow cancellation of specified dangerous actions during the timelock. Membership, appointment/removal, conflicts of interest and the exact cancellation scope remain to be published before activation.','早期 5-of-9 守護者方案擬允許在時間鎖期間取消指定危險操作。啟用前須公布成員、任免、利益衝突處理及取消權限範圍。'))+h('section-5',t('Before a proposal can be submitted','開放提交前的條件'))+p(t('Publish the governor and timelock addresses, supported interface, delegation method, quorum denominator, vote-counting rules and a worked execution example. Do not send funds to an address merely because it is labelled governance.','須公布治理與時間鎖地址、操作介面、委託方式、法定參與分母、票數計算及完整執行範例；不能僅因地址被標示為治理便向其轉帳。'))+h('section-6',t('Parameters retained for review','保留供審閱的參數'))+table([t('Item','項目'),t('Earlier proposal — not active','早期方案 · 尚非生效參數')],[[t('Proposal threshold','提案門檻'),'10,000 MHA '+t('equivalent delegated voting power','等值委託投票權')],[t('Pending / voting / execution delay','待啟動／投票／執行延遲'),t('1 hour / 5 days / 2 days','1 小時／5 天／2 天')],[t('Quorum','法定參與'),t('Earlier text: 20% of total MHA supply. Whether this means eligible/delegated voting supply must be resolved; these are different denominators.','早期文字為 MHA 總供應量的 20%。是否應採合資格／已委託投票供應量須先解決；兩者分母不同。')]])+p(link(l,'/learning/governance',t('Roles and authority','角色與權限'))));
 doc(l,'/solutions/opstack',t('Why M Hash uses an OP Stack design','為何 M Hash 採用 OP Stack 設計'),h('section-1',t('Design objectives','設計目標'))+p(t('The design aims to reuse an EVM-oriented rollup framework for application execution, batching and L1 settlement integration. Reusing a framework can reduce bespoke engineering, but MAGNE-specific changes require their own testing and review.','此設計旨在重用面向 EVM 的 Rollup 框架，支援應用執行、批次處理及 L1 結算整合。重用框架可減少自行開發工作，但 MAGNE 特定改動仍須獨立測試與審查。'))+h('section-2',t('What reuse does and does not establish','重用框架的範圍'))+ul([t('Execution and rollup components have separate responsibilities; deployment requires more than an execution client.','執行與 Rollup 組件各有職責；部署不只是執行客戶端。'),t('Using OP Stack does not automatically establish Superchain membership, a live bridge or interoperability with every other rollup.','使用 OP Stack 不自動構成 Superchain 成員身份、已啟用橋接或與所有 Rollup 的互通。'),t('Data publication, settlement contracts, proof configuration and upgrade authority must be documented for the actual network.','須按實際網絡列明資料發布、結算合約、證明配置與升級權限。')])+h('section-3',t('Implementation references','實作依據'))+p(link(l,'/networks/l2',t('L2 role map','L2 角色圖'))+' · '+link(l,'/solutions/optimizations',t('Optimisation proposals','優化方案'))+' · <a href="https://specs.optimism.io/protocol/derivation.html">OP Stack derivation specification</a>'));
 doc(l,'/solutions/optimizations',t('M Hash optimisation proposals','M Hash 優化方案'),p(t('The items below preserve the earlier engineering proposals. Their inclusion does not establish deployment or a measured speed-up. A release claim requires the relevant code change, configuration and reproducible benchmark.','下列保留早期工程方案，不據此宣稱已部署或已有實測加速。發布成果須附對應程式改動、配置及可重現基準測試。'))+h('section-1',t('Execution layer','執行層'))+table([t('Proposal','方案'),t('What must be validated','須驗證事項')],[[t('Shared intermediate state cache (L1.5)','共享中間狀態快取（L1.5）'),t('Cache ownership, memory limits, invalidation and reorganisation handling.','快取所有權、記憶體上限、失效及重組處理。')],[t('Diff-layer depth 128 → 32','Diff Layer 深度 128 → 32'),t('Read amplification, false positives and memory/disk trade-offs under the same workload.','同一工作負載下的讀取放大、誤判及記憶體／磁碟取捨。')],['originStorage '+t('prefetch sharing','預取共享'),t('Thread safety, hit rate and consistent state reads.','執行緒安全、命中率及狀態讀取一致性。')],[t('Reuse block execution results','重用區塊執行結果'),t('Payload identity, fork/version compatibility and required revalidation. Engine API versions must match the client.','酬載身份、分叉／版本相容性及必要重驗；Engine API 版本須與客戶端匹配。')]])+h('section-2',t('Batch publication','批次發布'))+p(t('Asynchronous batch submission may reduce waiting between publications, but must track L1 inclusion, replacement and reorganisation recovery. The old “15 confirmations / 45 seconds” example is not a confirmed current setting. Batch submission latency and settlement finality must be measured separately.','非同步批次提交可能減少發布間等待，但須追蹤 L1 納入、替換與重組恢復。舊稿「15 次確認／45 秒」不是已確認的現行設定；批次提交延遲與結算最終確定須分開測量。'))+h('section-3',t('Acceptance evidence','驗收依據'))+p(t('For each adopted change, publish the repository and commit, client version, configuration, test workload, before/after measurements and failure-case results. Until then these remain proposals, not published throughput guarantees.','每項採用的改動應列出倉庫與 commit、客戶端版本、配置、測試負載、前後對照及故障情境結果；此前維持方案狀態，不作吞吐量保證。')));
 doc(l,'/solutions/security',t('Application security boundaries','應用安全邊界'),h('section-1',t('From authorisation to execution','由授權到執行'))+p(t('A secure application must validate user intent, restrict permissions and expose transaction details before signing. Hardware key protection helps protect key material; it does not make an arbitrary contract call safe or remove the need to verify the recipient and requested authority.','安全應用須核對使用者意圖、限制權限，並在簽署前展示交易內容。硬件金鑰保護有助保護金鑰資料，但不會讓任意合約呼叫變得安全，也不能省略接收者與授權範圍核對。'))+h('section-2',t('On-chain records','鏈上紀錄'))+p(t('Records can be inspected through the relevant explorer. Their finality depends on the network protocol; upgradeable contracts, privileged operations and off-chain inputs have separate trust assumptions. An audit covers its specified code version and scope, not every future deployment.','可透過對應瀏覽器查閱紀錄，其最終確定性取決於網絡協議；可升級合約、特權操作與鏈外輸入各有信任假設。審計覆蓋指定程式版本與範圍，不延伸至所有後續部署。'))+h('section-3',t('Operational controls','營運控制'))+ul([t('Publish contract versions and administrative permissions.','公布合約版本與管理權限。'),t('Monitor incidents, document upgrades and define recovery procedures.','監察事件、記錄升級並制定恢復流程。'),t('Use least-privilege approvals and independently check high-impact transactions.','採最小權限授權，對高影響交易作獨立核對。')])+p(link(l,'/solutions/hardware',t('Hardware protection layers','硬件保護層'))));
 doc(l,'/solutions/hardware',t('Hardware: security and computation','硬件：安全與運算'),p(t('MAG1 brings device computation, protected key operations and network access into one product. These roles are distinct; supported features depend on the device, software and application configuration.','MAG1 結合裝置運算、受保護金鑰操作與網絡存取。各角色互相區分，支援功能以装置、軟件及應用配置為準。'))+img('9b5b6fb817a8-pg.png')+img('71ac8d8be3bd-Hardware01.png')+h('section-1',t('Three security layers','三層安全設計'))+p(t('The official security description references UTEE (CC EAL2+), HyperSeed N60 (CC EAL6+) and HyperSeed 72B (CC EAL6+). These are component or evaluated-scope references, not an EAL rating for the whole phone.','官方安全說明引用 UTEE（CC EAL2+）、HyperSeed N60（CC EAL6+）與 HyperSeed 72B（CC EAL6+）。這些是元件或受評範圍的認證參考，不是整機 EAL 等級。'))+h('section-4','HyperSeed N60')+p(t('The secure-element path is designed to keep protected keys inside the hardware and return signatures or authorised results. Actual use depends on the wallet, access rules and user authorisation; not every application transaction automatically follows this path.','安全元件路徑旨在將受保護金鑰留在硬件內，只回傳簽章或獲授權結果。實際使用取決於錢包、存取規則及使用者授權；並非每個應用的交易都自動經過此路徑。'))+img('2959ff813478-Hardware02.png')+h('section-5','HyperSeed 72B')+p(t('The separate NFC recovery design protects recovery material. Recovery access and backup handling must follow the configured procedure. Retention and endurance depend on the applicable component specification and operating conditions.','獨立 NFC 復原設計用於保護復原資料。復原存取與備份處理須遵循配置程序；保存年限與讀寫耐用度依適用元件規格及操作條件而定。'))+img('3b8267fa1b4c-Hardware03.png')+h('section-6','UTEE')+p(t('A trusted execution environment separates designated sensitive operations from ordinary applications. It is a different protection boundary from the secure element.','可信執行環境將指定敏感操作與一般應用分隔，與安全元件屬不同保護邊界。'))+img('8868149de808-Hardware04.png')+h('section-7',t('System security','系統安全'))+p(t('Permission checks, trusted execution, secure signing, software updates and operational testing work together. These controls reduce exposure; they do not promise immunity from malware, malicious approvals or implementation flaws.','權限核對、可信執行、安全簽署、軟件更新及營運測試共同降低風險，但不承諾完全免受惡意軟件、惡意授權或實作缺陷影響。'))+h('section-8',t('Certification references','認證依據'))+p('<a href="https://www.magne.ai/en/security.html">MAGNE Security</a> · '+link(l,'/learning/milestone#security-certifications',t('Certification history','認證歷史')))+p(t('The certificate holder, evaluated version, scope and augmentation apply to the corresponding original document.','證書持有人、受評版本、範圍及增強項以對應原件為準。'))+h('section-9',t('On-device AI','端側 AI'))+p(t('Local inference can reduce dependence on cloud processing for supported workloads. Translation, assistance and detection use cases require their own model, application and device testing; running locally does not by itself establish complete privacy.','本機推論可減少支援工作負載對雲端處理的依賴。翻譯、助理與偵測等場景須分別完成模型、應用與裝置測試；本機執行本身不等於完全私隱。'))+h('section-10',t('Network participation','網絡參與'))+p(t('Wallets and applications can access supported networks. Proposed GEN1 rewards concern eligible device tasks and availability, not automatic L1 validator status or L2 consensus rights.','錢包與應用可存取支援網絡。擬議 GEN1 獎勵針對合資格裝置任務與可用性，不自動授予 L1 驗證者身份或 L2 共識權。'))+h('section-11',t('Applications and delivery','應用與交付'))+p(t('Application availability and device delivery are separate milestones. See the product progress chapter for first-batch delivery and subsequent-batch updates.','應用可用性與裝置交付是不同里程碑。首批交付與後續批次更新見產品進度章節。'))+p(link(l,'/learning/milestone#mag1-delivery',t('MAG1 delivery update','MAG1 交付更新'))));
 doc(l,'/solutions/poai-depin',t('PoAI and DePIN participation','PoAI 與 DePIN 參與'),p(t('The design explores distributed device computation with verifiable task results. PoAI is used here as a project design term for AI-work verification, not as a claim that useful AI work automatically proves blockchain consensus.','此設計探索可核驗任務結果的分散式裝置運算。PoAI 在此指項目對 AI 工作核驗的設計用語，不表示有用 AI 運算自動構成區塊鏈共識證明。'))+h('section-1',t('Task lifecycle','任務生命週期'))+ul([t('Define the task, input permissions, workload reference and acceptance criteria.','定義任務、輸入權限、工作量基準及驗收條件。'),t('Assign eligible devices and collect results with time and device evidence.','分派合資格裝置，收集結果與時間、裝置證據。'),t('Validate quality and detect duplicate, fabricated or ineligible work before settlement.','結算前核驗品質，識別重複、虛構或不合資格工作。')])+h('section-2',t('Device network','裝置網絡'))+p(t('DePIN describes a network of contributed physical infrastructure. Devices sold, registered devices, online devices and accepted-task contributors are different counts. This chapter does not assert an active network of millions of devices.','DePIN 指由實體基礎設施貢獻形成的網絡。已售、已登記、在線及有效任務貢獻裝置是不同統計口徑；本章不宣稱已存在數百萬台活躍裝置網絡。'))+h('section-3',t('Rewards and activation','獎勵與啟用'))+p(t('GEN1 reward budgeting and release are specified in Tokenomics. The task catalogue, benchmark, verification method and activation date still require publication. Device participation is not an unconditional income entitlement.','GEN1 獎勵預算與釋放見代幣經濟章節。任務目錄、基準、核驗方式及啟用日期仍須公布；裝置參與不構成無條件收益權。'))+p(link(l,'/learning/tokenomics#gen1-calculator',t('GEN1 scenarios','GEN1 情境測算'))));
 doc(l,'/learning/magne-dapp',t('MAGNE dApp — planned hub','MAGNE dApp · 規劃中的入口'),p(t('The earlier whitepaper used Shin Getter Nexus as the working name for a proposed dApp hub. This name does not identify a separately confirmed production release.','早期白皮書以 Shin Getter Nexus 作為擬議 dApp Hub 的工作名稱，該名稱不代表另有已確認的正式發布產品。'))+img('eed88537d54c-dapp.png')+h('section-1',t('Planned functions','規劃功能'))+p(t('The hub concept groups applications, developer tools and network services into a shared entry point. Each application must disclose its network, permissions and release status.','Hub 概念將應用、開發工具及網絡服務整理為統一入口；各應用須分別披露網絡、權限及發布狀態。'))+h('section-2',t('Current product references','目前產品入口'))+p(t('W3 and AgentPay have their own preview, sandbox and testnet descriptions. Their availability does not by itself mean the proposed hub or production payment service has launched.','W3 與 AgentPay 各有預覽、沙盒及測試網狀態；相關頁面可用不代表擬議 Hub 或正式支付服務已上線。'))+p('<a href="https://w3.magne.ai/">W3</a> · <a href="https://w3.magne.ai/agentpay.html">AgentPay</a>'));
}
console.log('Reconciled governance, security, hardware and application design chapters.');
